const input={workflow:'Purchase Order',budgetId:'61',territory:'North',department:'',submitterId:'19',amount:'55.00',hasBudgetModification:false,hasBudgetOverrun:false};
const clone=value=>JSON.parse(JSON.stringify(value));
function runtime({context=input,policyRow=policy,login='test-owner',environment='Production',users,extraTables={},mailFailure=false,deleteFailure=false}={}){
  const tables={Approval_Policy:[clone(policyRow)],Approval_Role:[{ID:1,Role_Name:'CFO',Active:true}],Approval_Role_Assignment:[{ID:21,Role:1,Company:31,Person:12,Active:true,Territory_Key:'',Department_Key:'',Effective_From:null,Effective_To:null}],User_Access:users||[{ID:19,User:'test-owner',Full_Name:'Robby Belliveau',Approver_Email:'legal@example.com',Approval_Routing_Enabled:false},{ID:12,User:'normal-cfo',Full_Name:'Normal CFO',Approver_Email:'normal@example.com',Approval_Routing_Enabled:true}],Territory:[],Company:[{ID:31}],Add_Budget:[{ID:61}],Approval_Config_Audit:[],Approval_Config_Lock:[],PO_Phase_Lock:[],PO_Item:[],PO_Operation:[],Budget_Modification:[],Budget_Approvals:[],Payment_Request:[],Approval_Route_Snapshot:[],...clone(extraTables)};
  const c=vm.createContext({tables:clone(tables),payload:clone(context),login,environment,mailFailure,deleteFailure});
  vm.runInContext(`
  tables=JSON.parse(JSON.stringify(tables));payload=JSON.parse(JSON.stringify(payload));
  function map(v){if(!v||typeof v!=='object'||Object.prototype.hasOwnProperty.call(v,'get'))return v;if(Array.isArray(v))return v.map(map);for(var k of Object.keys(v))v[k]=map(v[k]);Object.defineProperties(v,{get:{value:function(k){return this[k]??null;}},put:{value:function(k,v){this[k]=map(v);}},remove:{value:function(k){delete this[k];}},keys:{value:function(){return Object.keys(this);}},toString:{value:function(){return JSON.stringify(this);}}});return v;}
  function Map(){return map({});}function List(){return [];}function ifnull(v,f){return v==null?f:v;}function choose(c,a,b){return c?a:b;}
  function recordValues(...pairs){var data={};for(var i=0;i<pairs.length;i+=2)data[pairs[i]]=pairs[i+1];return map(data);}
  Array.prototype.add=function(v){this.push(v);};Array.prototype.get=function(i){return this[i]??null;};Array.prototype.count=Array.prototype.size=function(){return this.length;};Array.prototype.contains=function(v){return this.includes(v);};Array.prototype.toString=function(){return JSON.stringify(this);};
  function nativeJSON(v){if(Array.isArray(v))return v.map(nativeJSON);if(v!==null&&typeof v==='object'){var sorted={};for(var key of Object.keys(v).sort())sorted[key]=nativeJSON(v[key]);return sorted;}return v;}
  String.prototype.toLong=String.prototype.toDecimal=function(){return Number(this);};String.prototype.toDate=function(){return this.toString();};String.prototype.toJSONList=function(){return JSON.parse(this).map(item=>item!==null&&typeof item==='object'?JSON.stringify(nativeJSON(item)):item);};String.prototype.toMap=function(){return map(JSON.parse(this));};String.prototype.matches=function(r){return new RegExp('^(?:'+r+')$').test(this);};String.prototype.replaceAll=function(a,b){return this.replace(new RegExp(a,'g'),b);};Number.prototype.toLong=function(){return Math.trunc(this);};
  var writes=0,rollups=0,mails=[],zoho={loginuser:login,adminuser:'test-owner',currentdate:'2026-10-11',appuri:'https://example.invalid/po-test',encryption:{sha256(value){return 'test-proof:'+value;}}};
  function record(row){return new Proxy(row,{get(o,k){return o[k]??null;},set(o,k,v){writes++;o[k]=v;return true;}});}
  function query(form,predicate,sort){var result=(tables[form]||[]).map(record).filter(predicate);if(sort)result.sort((a,b)=>a[sort]-b[sort]);return new Proxy(result,{get(a,k){return k in a||typeof k==='symbol'?a[k]:a[0]?.[k]??null;},set(a,k,v){if(!a.length)throw Error('Missing record');a[0][k]=v;return true;}});}
  function insertRecord(form,data){if(form==='PO_Phase_Lock'&&tables[form].some(row=>row.Phase_Key===data.Phase_Key))throw Error('Phase lock is owned by another operation');data.ID=Math.max(100,...tables[form].map(row=>row.ID))+1;tables[form].push(data);writes++;return data.ID;}
  function removeRecords(form,rows){if(deleteFailure)throw Error('Retained lock deletion interrupted');tables[form]=tables[form].filter(row=>!rows.some(removed=>row.ID===removed.ID));writes++;}
  function sendMail(message){if(mailFailure)throw Error('Test delivery failed');mails.push(clone(message));}
  function clone(value){return JSON.parse(JSON.stringify(value));}
  var thisapp={poCurrencyString(v){if(typeof v!=='string'||!/^\\d+(?:\\.\\d{1,2})?$/.test(v))return '';var parts=v.split('.');return parts[0]+'.'+(parts[1]||'').padEnd(2,'0');},recalcBudgetModifiedTotals(){rollups++;},recalcItemRevisedFinal(){rollups++;},poBudgetBalances(){return map({success:true,balances:[]});},approvalConfigurationSnapshot(){return map({success:true,configuration:{policies:[],roles:[],assignments:[]}});}};
  var request=map(payload);
  thisapp.environment={type:environment};
  String.prototype.toFile=function(name){return {name,content:this.toString()};};
  `+names.map(name=>programs[name]+`;thisapp.${name}=${name};`).join('\n'),c);
  return {c,run:(name,value)=>{c.argument=clone(value);return clone(vm.runInContext(`${name}(map(argument))`,c));},tables:()=>clone(c.tables)};
}
