for(const company of [32,null]){const duplicate={...normalPolicy,ID:42,Company:company};r=runtime({policyRow:normalPolicy,extraTables:{Approval_Policy:[normalPolicy,duplicate]}});const ambiguous=r.run('resolveApprovalRoute',input);assert.equal(ambiguous.success,false);assert.match(ambiguous.error,/ambiguous/);assert.equal(r.c.writes,0,'Removed company scope cannot conceal colliding policy records');}

