assert.deepEqual(r.run('resolveApprovalRoute',{...input,hasBudgetModification:false}).snapshot.route.map(row=>row.role),['CFO']);
for(const members of [[],[{ID:999}]]){const tables=clone(devMgrTables);tables.Territory[0].Dev_Mgr=members;r=runtime({policyRow:devMgrPolicy,extraTables:tables});assert.equal(r.run('resolveApprovalRoute',{...input,hasBudgetModification:true}).success,false);assert.equal(r.c.writes,0);}
for(const broken of [{Approval_Routing_Enabled:false},{Approver_Email:''},{User:''}]){const tables=clone(devMgrTables);Object.assign(tables.User_Access[1],broken);r=runtime({policyRow:devMgrPolicy,extraTables:tables});assert.equal(r.run('resolveApprovalRoute',{...input,hasBudgetModification:true}).success,false,'Every selected manager must be routable');assert.equal(r.c.writes,0);}
