// Exercise the normal captured route through bundle validation and manual decision,
// rather than only the policy preview or the historical test-CFO exception.
function ordinaryOwnPO(){const t=submitted();const captured=clone(normal.snapshot);captured.context={...input,submitterId:'12',recordId:'51',submissionRevision:'revision-one',modifications:[]};t.Approval_Route_Snapshot[0].Route_JSON=JSON.stringify(captured);t.Approval_Route_Snapshot[0].Context_JSON=JSON.stringify(captured.context);t.Budget_Approvals[0].Approver='normal@example.com';return t;}
r=runtime({extraTables:ordinaryOwnPO(),login:'normal-cfo'});bundle=r.run('poApprovalBundle','51');assert.equal(bundle.success,true,JSON.stringify(bundle));assert.equal(bundle.bundle.canApprove,true);assert.equal(bundle.bundle.rows[0].status,'Pending');assert.equal(r.c.writes,0,'Reading own PO never auto-approves');prepareDecision(r);outcome=r.run('handlePurchaseOrderApproval',{...decision,userAccessId:'12'});assert.equal(outcome.success,true,JSON.stringify(outcome));assert.equal(r.tables().Budget_Approvals[0].Status,'Approved');
r=runtime({extraTables:ordinaryOwnPO(),login:'test-owner'});prepareDecision(r);assert.equal(r.run('handlePurchaseOrderApproval',decision).success,false);assert.equal(r.c.writes,0,'Unassigned submitter/owner still cannot decide');
r=runtime({extraTables:ordinaryOwnPO(),environment:'Development'});hintBundle=r.run('poApprovalBundle','51').bundle;const ownHint=JSON.parse(vm.runInContext(`poActorResponse(map(${JSON.stringify({success:true,snapshot:{approvalBundle:hintBundle}})}),'12').toString()`,r.c));assert.equal(ownHint.snapshot.approvalBundle.canApprove,true);
const duplicateOwn=ordinaryOwnPO();const duplicated=JSON.parse(duplicateOwn.Approval_Route_Snapshot[0].Route_JSON);duplicated.route.push({...duplicated.route[0],order:2,key:'duplicate'});duplicateOwn.Approval_Route_Snapshot[0].Route_JSON=JSON.stringify(duplicated);duplicateOwn.Approval_Route_Snapshot[0].Execution_JSON='["101","102"]';duplicateOwn.Budget_Approvals.push({...duplicateOwn.Budget_Approvals[0],ID:102,Sort_Order:2});r=runtime({extraTables:duplicateOwn,login:'normal-cfo'});assert.equal(r.run('poApprovalBundle','51').success,false);assert.equal(r.c.writes,0);
console.log('Ordinary submitting approver: captured bundle, manual decision and Dev actor hints allow own PO; no auto-approval, no unassigned decision and no duplicate people.');
// Recovery runs the actual saved-PO snapshot reader, not just the route preview.
const snapshotProgram=compile(fs.readFileSync('creator/functions/poSnapshot.dg','utf8').replace(/\brow\b/g,'storedPOLine'));
function recoveryTables(){const t=ordinaryOwnPO();Object.assign(t.Payment_Request[0],{Vendor:91,PO_Line_Count:1,PO_Budget_Modification:null,Budget_Item:null,Accounting_Project_Code:null,Element:null,Final_Accounting_Code:null,Request_Amount:55});t.User_Access=[{ID:12,User:'normal-cfo',Full_Name:'Normal CFO',Approver_Email:'normal@example.com',Approval_Routing_Enabled:true,Edit_All_Budgets:true}];t.Add_Budget=[{ID:61,Archived:false,Budget_Owner:[]}];t.Budget_Item=[{ID:71,Budget:61}];t.PO_Item=[{ID:201,Purchase_Order:51,Budget_Item:71,Revision:'revision-one',Line_Order:1,Line_Key:'only',Revision_Line_Key:'revision-one-only',Final_Amount:55,Final_Amount_Exact:'55.00',Description:'Test',Cost_Element:'5',UOM:'EA',Cost_Code:'CB01-4130',Pricing_Mode:'Manual',Quantity:null,Quantity_Exact:null,Unit_Price:null,Unit_Price_Exact:null}];t.PO_Operation=[{ID:301,Token:'revision-one',Budget:61,Actor:12,Purchase_Order:51,Status:'Unknown',Error_Text:'PO approval steps must use distinct people and exclude the submitter.',Request_JSON:JSON.stringify({action:'Submit',token:'revision-one',budgetId:'61',lineCount:1,digest:'original-request'})}];t.PO_Phase_Lock=[{ID:302,Phase_Key:'61',Operation_Token:'revision-one',Actor:12}];return t;}
function nativeRecoveryRuntime(t=recoveryTables(),extra={}){const rr=runtime({extraTables:t,login:'normal-cfo',...extra});vm.runInContext(snapshotProgram+';thisapp.poSnapshot=poSnapshot;',rr.c);return rr;}
const recoveryPayload={action:'Recover',id:'51',budgetId:'61',userAccessId:'12',expectedRevision:'revision-one',token:'revision-one'};
function recoveryCall(rr,p=recoveryPayload){rr.c.recoveryPayload=JSON.stringify(p);return JSON.parse(vm.runInContext('managePurchaseOrder(recoveryPayload)',rr.c));}
r=nativeRecoveryRuntime();const recoveryBusinessBefore=r.tables();let recGet=recoveryCall(r,{...recoveryPayload,action:'Get'});assert.equal(recGet.recoveryAvailable,true,JSON.stringify(recGet));const recDelete=recoveryCall(r,{...recoveryPayload,action:'PreviewDelete'});assert.equal(recDelete.recoveryAvailable,true);assert.equal(recDelete.recoveryToken,'revision-one');assert.equal(r.c.writes,0);
prepareDecision(r);const lockedDecision=r.run('handlePurchaseOrderApproval',{...decision,userAccessId:'12'});assert.equal(lockedDecision.writeState,'not-started');assert.match(lockedDecision.error,/Recover/);assert.equal(r.c.writes,0);
vm.runInContext(snapshotProgram+';thisapp.poSnapshot=poSnapshot;',r.c);const rec=recoveryCall(r);assert.equal(rec.success,true,JSON.stringify(rec));assert.equal(r.tables().PO_Phase_Lock.length,0);assert.equal(r.tables().PO_Operation[0].Status,'Complete');for(const table of ['Payment_Request','PO_Item','Budget_Approvals','Approval_Route_Snapshot','Budget_Modification','Budget_Item','Add_Budget'])assert.deepEqual(r.tables()[table],recoveryBusinessBefore[table],table+' remains unchanged by recovery');assert.equal(r.c.rollups,0);assert.equal(r.c.mails.length,0);const recoveryWrites=r.c.writes;assert.equal(recoveryCall(r,{...recoveryPayload,action:'CheckRecovery'}).success,true);assert.equal(r.c.writes,recoveryWrites,'CheckRecovery is read-only');assert.equal(recoveryCall(r,{...recoveryPayload,action:'PreviewDelete'}).success,true,'Recovered PO can be previewed for deletion');
for(const mutate of [t=>t.PO_Operation[0].Status='Started',t=>t.PO_Operation[0].Actor=19,t=>t.PO_Phase_Lock[0].Actor=19,t=>t.PO_Phase_Lock[0].Operation_Token='foreign',t=>t.Payment_Request[0].PO_Revision='newer',t=>t.PO_Operation[0].Request_JSON=JSON.stringify({action:'Draft',token:'revision-one',budgetId:'61',lineCount:1,digest:'x'}),t=>t.PO_Phase_Lock.push({ID:303,Phase_Key:'61',Operation_Token:'other',Actor:19}),t=>t.PO_Item=[],t=>t.Budget_Approvals[0].Status='Approved']){const t=recoveryTables();mutate(t);r=nativeRecoveryRuntime(t);assert.equal(recoveryCall(r).success,false);assert.equal(r.c.writes,0,'Invalid/active/foreign recovery changes nothing');assert.equal(r.c.mails.length,0);}
r=nativeRecoveryRuntime(recoveryTables(),{deleteFailure:true});assert.equal(recoveryCall(r).writeState,'unknown');assert.equal(r.tables().PO_Operation[0].Status,'Complete');assert.equal(r.tables().PO_Phase_Lock.length,1);const interruptedRecoveryWrites=r.c.writes;assert.equal(recoveryCall(r,{...recoveryPayload,action:'CheckRecovery'}).success,false);assert.equal(r.c.writes,interruptedRecoveryWrites);
const notesTables=ordinaryOwnPO();notesTables.Budget_Approvals[0].Approval_Notes='Prior note';r=runtime({extraTables:notesTables,login:'normal-cfo'});prepareDecision(r);assert.equal(r.run('handlePurchaseOrderApproval',{...decision,userAccessId:'12'}).writeState,'not-started');assert.equal(r.tables().PO_Phase_Lock.length,0,'Prior-note rejection happens before lock acquisition');assert.equal(r.c.writes,0);
